import{_ as i,o as l,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Steve Quenette/Blair Bethwaite -- Servicing the Fabric and the Workshop","description":"","frontmatter":{"title":"Steve Quenette/Blair Bethwaite -- Servicing the Fabric and the Workshop","date":"2015-11-13T00:00:00.000Z","updated":"2015-11-14T00:00:00.000Z","tags":["分布式存储","Ceph","科研ICT","软件定义存储","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/Steve_Quenette_Blair_Bethwaite_--_Servicing_the_Fabric_and_the_Workshop.md","filePath":"posts/2015/Steve_Quenette_Blair_Bethwaite_--_Servicing_the_Fabric_and_the_Workshop.md","lastUpdated":1780459816000}'),r={name:"posts/2015/Steve_Quenette_Blair_Bethwaite_--_Servicing_the_Fabric_and_the_Workshop.md"};function h(o,e,n,s,_,u){return l(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（请在此处填写会议具体时间）</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>（请在此处填写会议具体地点）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>（请在此处填写参会人员名单）</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>探讨ICT技术在科研和企业应用中的差异，以及如何通过Ceph等分布式存储技术实现大规模和性能提升。</p><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ul><li><strong>科研与企业的ICT差异</strong>： <ul><li>科研ICT更注重规模和性能，需要构建支持研究者构建事物的平台。</li><li>企业ICT更关注长尾用户，追求成本最低化。</li><li>科研ICT需要同时支持峰值用户和长尾用户。</li></ul></li><li><strong>渗透性</strong>： <ul><li>渗透性指的是组织与外部组织互动，共同实现目标。</li><li>科研ICT需要具备渗透性，与其他组织合作，实现共同目标。</li></ul></li><li><strong>多学科研究</strong>： <ul><li>多学科研究是科研的重要趋势，跨学科合作能带来突破性发现。</li></ul></li><li><strong>发现范式</strong>： <ul><li>发现范式受技术驱动，经历了显微镜、物理定律、计算和大数据四个阶段。</li><li>第四范式以数据为中心，需要强大的计算和存储能力。</li></ul></li><li><strong>Ceph在科研中的应用</strong>： <ul><li>Ceph作为分布式存储技术，能够满足科研对规模和性能的需求。</li><li>Ceph支持自服务、多租户、质量服务等特性。</li><li>Ceph与OpenStack等软件定义存储技术结合，构建灵活的科研基础设施。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ul><li>科研ICT与企业的ICT差异</li><li>渗透性在科研ICT中的应用</li><li>多学科研究对科研基础设施的需求</li><li>发现范式对科研技术的影响</li><li>Ceph在科研中的应用和挑战</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li>继续推进Ceph在科研中的应用，并解决相关挑战。</li><li>加强与OpenStack等软件定义存储技术的结合。</li><li>与其他组织合作，共同推动科研ICT的发展。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>深入研究Ceph的性能优化和故障处理。</li><li>开发针对科研场景的Ceph解决方案。</li><li>推动Ceph社区发展，吸引更多科研机构加入。</li></ul><h4 id="其他" tabindex="-1">其他： <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他：&quot;">​</a></h4><ul><li>会议中提到Ceph集群的部署和性能优化经验。</li><li>会议中讨论了Ceph与其他存储技术的比较。</li><li>会议中分享了一些科研ICT的案例。</li></ul><h3 id="关键词" tabindex="-1">关键词： <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词：&quot;">​</a></h3><ul><li>ICT</li><li>科研</li><li>企业</li><li>Ceph</li><li>分布式存储</li><li>OpenStack</li><li>软件定义存储</li><li>渗透性</li><li>多学科研究</li><li>发现范式</li><li>规模</li><li>性能</li><li>自服务</li><li>多租户</li><li>质量服务</li></ul>',21)])])}const p=i(r,[["render",h]]);export{c as __pageData,p as default};
